import{_ as i,o as a,c as o,a as t}from"./app.DLiRGumz.js";const p=JSON.parse('{"title":"Ln Delegation Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"governance/DELEGATION_ARCHITECTURE_LN.md","filePath":"governance/DELEGATION_ARCHITECTURE_LN.md","lastUpdated":1771823011000}'),n={name:"governance/DELEGATION_ARCHITECTURE_LN.md"};function l(r,e,s,c,d,h){return a(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="ln-delegation-architecture" tabindex="-1">Ln Delegation Architecture <a class="header-anchor" href="#ln-delegation-architecture" aria-label="Permalink to &quot;Ln Delegation Architecture&quot;">​</a></h1><h2 id="objective" tabindex="-1">Objective <a class="header-anchor" href="#objective" aria-label="Permalink to &quot;Objective&quot;">​</a></h2><p>Define universal delegation planning for all domains and task types across <code>L1 -&gt; ... -&gt; Ln</code>.</p><h2 id="role-layers" tabindex="-1">Role Layers <a class="header-anchor" href="#role-layers" aria-label="Permalink to &quot;Role Layers&quot;">​</a></h2><ol><li><code>L1</code> Orchestrator: scope, constraints, global decisions, final integration.</li><li><code>L2</code> Domain Managers: backend, frontend, infra, data, security, docs, release.</li><li><code>L3</code> Specialists: protocol, schema, CI, performance, reliability, compliance.</li><li><code>Ln</code> Workers: execution units with explicit file/domain ownership.</li></ol><h2 id="universal-delegation-decision-engine" tabindex="-1">Universal Delegation Decision Engine <a class="header-anchor" href="#universal-delegation-decision-engine" aria-label="Permalink to &quot;Universal Delegation Decision Engine&quot;">​</a></h2><p>Classify each task by:</p><ol><li>Domain.</li><li>Scale (<code>XS/S/M/L/XL</code>).</li><li>Risk (<code>low/medium/high/critical</code>).</li><li>Coupling (<code>isolated/cross-module/cross-repo</code>).</li><li>Runtime profile (<code>cpu/io/interactive/long-running</code>).</li><li>Validation depth (<code>lint/unit/integration/e2e/security/perf/chaos/accessibility</code>).</li></ol><p>The engine outputs:</p><ol><li>Required layer (<code>L2/L3/Ln</code>) and count.</li><li>Worktree placement mode.</li><li>Commit package strategy.</li><li>Required test and governance gates.</li></ol><h2 id="delegation-contracts" tabindex="-1">Delegation Contracts <a class="header-anchor" href="#delegation-contracts" aria-label="Permalink to &quot;Delegation Contracts&quot;">​</a></h2><p>Every delegated task must include:</p><ol><li>Goal and acceptance criteria.</li><li>Allowed and forbidden paths.</li><li>Required checks/tests.</li><li>Output contract: patch, evidence, risks, next actions.</li><li>Timeout and escalation behavior.</li></ol><h2 id="concurrency-and-contention-rules" tabindex="-1">Concurrency and Contention Rules <a class="header-anchor" href="#concurrency-and-contention-rules" aria-label="Permalink to &quot;Concurrency and Contention Rules&quot;">​</a></h2><ol><li>Prefer parallel workers when ownership sets are disjoint.</li><li>Use file-claim registry before edits.</li><li>Escalate to burst worktree when overlap-risk exceeds threshold.</li><li>Preserve both branches/artifacts on conflict.</li></ol><h2 id="optimization-extensions" tabindex="-1">Optimization Extensions <a class="header-anchor" href="#optimization-extensions" aria-label="Permalink to &quot;Optimization Extensions&quot;">​</a></h2><ol><li>Cost model: estimated runtime, CI minutes, token spend.</li><li>Confidence scoring for worker outputs.</li><li>Auto-rebalance for blocked/late tasks.</li><li>Independent verification lane separate from implementation lane.</li><li>Consolidation pass before integration merge.</li></ol><h2 id="metrics-and-slos" tabindex="-1">Metrics and SLOs <a class="header-anchor" href="#metrics-and-slos" aria-label="Permalink to &quot;Metrics and SLOs&quot;">​</a></h2><ol><li>Delegation efficiency (<code>% tasks completed without L1 manual intervention</code>).</li><li>Conflict rate (<code>collisions per 100 tasks</code>).</li><li>Rework rate (<code>superseded pkg rate</code>).</li><li>First-pass validation success.</li><li>Mean time from task start to verified merge.</li></ol>',19)])])}const m=i(n,[["render",l]]);export{p as __pageData,m as default};
